SELECT 'gongkao', '词义辨析', 'kp-xingce-language-cloze-idiom-semantics', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "成语辨析：词义细微辨析"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "抽丝剥茧，抓住成语中不同那个字的字眼。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、高频辨析"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【不以为意】vs【不以为然】：意 = 在意（不放在心上）；然 = 这样（不认为是这样，不赞同）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【休戚相关】vs【息息相关】：休戚 = 祸福（利害关系一致）；息息 = 呼吸（关系密切，不带祸福）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "【防微杜渐】vs【未雨绸缪】：微 = 苗头（坏事刚冒头就去掐灭）；未雨 = 没下雨（坏事还没发生就去预防）。"}]}]}]}]}$$ AS jsonb), NULL, '词义辨析的核心考点与解题技巧。', category_node.id, CAST('["言语理解", "逻辑填空", "词义辨析"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_language_cloze_idiom_semantics", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
